import React, { useState, useEffect } from 'react';
import api from '../../services/api';
import { formatCurrency, formatDate, ORDER_STATUS_COLORS, ORDER_STATUS_LABELS } from '../../utils/roles';

const WaiterPage = () => {
  const [tables, setTables] = useState([]);
  const [products, setProducts] = useState([]);
  const [categories, setCategories] = useState([]);
  const [selectedTable, setSelectedTable] = useState(null);
  const [cart, setCart] = useState([]);
  const [orderType, setOrderType] = useState('dine_in');
  const [customerName, setCustomerName] = useState('');
  const [notes, setNotes] = useState('');
  const [activeTab, setActiveTab] = useState('new'); // 'new' | 'history'
  const [myOrders, setMyOrders] = useState([]);
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState('');

  useEffect(() => {
    fetchTables();
    fetchProducts();
    fetchMyOrders();
  }, []);

  const fetchTables = () => {
    api.get('/branches').then(res => {
      const branchId = res.data.data[0]?.id;
      if (branchId) {
        // Simulación: en producción sería /api/tables?branch_id=
        api.get('/dashboard').then(() => {
          // Mock tables para demo
          setTables([
            { id: 1, number: '01', name: 'Terraza 1', status: 'free', capacity: 4 },
            { id: 2, number: '02', name: 'Terraza 2', status: 'occupied', capacity: 4 },
            { id: 3, number: '03', name: 'Salón 1', status: 'free', capacity: 6 },
            { id: 4, number: '04', name: 'Salón 2', status: 'free', capacity: 6 },
            { id: 5, number: '05', name: 'VIP A', status: 'occupied', capacity: 8 },
          ]);
        });
      }
    });
  };

  const fetchProducts = async () => {
    // Usar el menú público para obtener productos
    const res = await api.get('/menu/SUC-001');
    const cats = res.data.data.categories;
    setCategories(cats);
    const allProducts = cats.flatMap(c => c.products.map(p => ({ ...p, categoryName: c.name })));
    setProducts(allProducts);
  };

  const fetchMyOrders = () => {
    api.get('/orders').then(res => setMyOrders(res.data.data.data || []));
  };

  const addToCart = (product) => {
    const existing = cart.find(item => item.product_id === product.id);
    if (existing) {
      setCart(cart.map(item =>
        item.product_id === product.id
          ? { ...item, quantity: item.quantity + 1 }
          : item
      ));
    } else {
      setCart([...cart, {
        product_id: product.id,
        name: product.name,
        price: product.price,
        quantity: 1,
        notes: '',
        modifiers: [],
      }]);
    }
  };

  const removeFromCart = (productId) => {
    setCart(cart.filter(item => item.product_id !== productId));
  };

  const updateQuantity = (productId, delta) => {
    setCart(cart.map(item => {
      if (item.product_id === productId) {
        const newQty = Math.max(1, item.quantity + delta);
        return { ...item, quantity: newQty };
      }
      return item;
    }));
  };

  const updateItemNotes = (productId, note) => {
    setCart(cart.map(item =>
      item.product_id === productId ? { ...item, notes: note } : item
    ));
  };

  const submitOrder = async () => {
    if (cart.length === 0) return;
    setLoading(true);

    try {
      const items = cart.map(item => ({
        product_id: item.product_id,
        quantity: item.quantity,
        notes: item.notes || undefined,
        modifiers: item.modifiers.length > 0 ? item.modifiers : undefined,
      }));

      await api.post('/orders', {
        branch_id: 1, // TODO: dinámico
        table_id: selectedTable?.id || null,
        customer_name: customerName || undefined,
        order_type: orderType,
        notes: notes || undefined,
        items,
      });

      setSuccess('¡Pedido enviado exitosamente!');
      setCart([]);
      setSelectedTable(null);
      setCustomerName('');
      setNotes('');
      fetchMyOrders();
      setTimeout(() => setSuccess(''), 3000);
    } catch (err) {
      alert(err.response?.data?.message || 'Error al enviar pedido');
    } finally {
      setLoading(false);
    }
  };

  const cartTotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);

  return (
    <div>
      <h1 style={{ color: '#e2e8f0', marginBottom: 24, fontSize: 28 }}>📝 Toma de Pedidos</h1>

      {/* Tabs */}
      <div style={{ display: 'flex', gap: 8, marginBottom: 24 }}>
        {[{ key: 'new', label: 'Nuevo Pedido', icon: '📝' }, { key: 'history', label: 'Mis Pedidos', icon: '📋' }].map(tab => (
          <button
            key={tab.key}
            onClick={() => setActiveTab(tab.key)}
            style={{
              padding: '12px 24px', borderRadius: 10, border: 'none',
              background: activeTab === tab.key ? '#38bdf8' : '#1e293b',
              color: activeTab === tab.key ? '#0f172a' : '#94a3b8',
              fontWeight: 600, cursor: 'pointer', fontSize: 14,
            }}
          >
            {tab.icon} {tab.label}
          </button>
        ))}
      </div>

      {success && (
        <div style={{
          background: 'rgba(16, 185, 129, 0.1)', border: '1px solid #10b981',
          color: '#10b981', padding: 16, borderRadius: 10, marginBottom: 20,
        }}>
          {success}
        </div>
      )}

      {activeTab === 'new' ? (
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 380px', gap: 24 }}>
          {/* Panel izquierdo: Productos */}
          <div>
            {/* Tipo de orden y mesa */}
            <div className="card" style={{ marginBottom: 20 }}>
              <div style={{ display: 'flex', gap: 16, flexWrap: 'wrap', alignItems: 'center' }}>
                <div>
                  <label style={{ color: '#94a3b8', fontSize: 12, display: 'block', marginBottom: 6 }}>Tipo de orden</label>
                  <select
                    value={orderType}
                    onChange={(e) => setOrderType(e.target.value)}
                    className="input"
                    style={{ width: 160 }}
                  >
                    <option value="dine_in">🪑 Comer aquí</option>
                    <option value="takeout">📦 Para llevar</option>
                    <option value="delivery">🛵 Delivery</option>
                  </select>
                </div>
                {orderType === 'dine_in' && (
                  <div>
                    <label style={{ color: '#94a3b8', fontSize: 12, display: 'block', marginBottom: 6 }}>Mesa</label>
                    <select
                      value={selectedTable?.id || ''}
                      onChange={(e) => {
                        const t = tables.find(t => t.id === parseInt(e.target.value));
                        setSelectedTable(t || null);
                      }}
                      className="input"
                      style={{ width: 160 }}
                    >
                      <option value="">Seleccionar...</option>
                      {tables.filter(t => t.status === 'free').map(t => (
                        <option key={t.id} value={t.id}>Mesa {t.number} — {t.name}</option>
                      ))}
                    </select>
                  </div>
                )}
                <div style={{ flex: 1, minWidth: 200 }}>
                  <label style={{ color: '#94a3b8', fontSize: 12, display: 'block', marginBottom: 6 }}>Cliente</label>
                  <input
                    type="text"
                    placeholder="Nombre del cliente (opcional)"
                    className="input"
                    value={customerName}
                    onChange={(e) => setCustomerName(e.target.value)}
                  />
                </div>
              </div>
            </div>

            {/* Productos */}
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(200px, 1fr))', gap: 12 }}>
              {products.map(product => (
                <div
                  key={product.id}
                  onClick={() => addToCart(product)}
                  className="card"
                  style={{
                    cursor: 'pointer', padding: 16,
                    transition: 'all 0.2s',
                  }}
                  onMouseEnter={(e) => {
                    e.currentTarget.style.borderColor = '#38bdf8';
                    e.currentTarget.style.transform = 'translateY(-2px)';
                  }}
                  onMouseLeave={(e) => {
                    e.currentTarget.style.borderColor = '#334155';
                    e.currentTarget.style.transform = 'translateY(0)';
                  }}
                >
                  <div style={{
                    width: '100%', height: 120, borderRadius: 10,
                    background: product.image_url ? `url(${product.image_url}) center/cover` : '#334155',
                    marginBottom: 10, display: 'flex', alignItems: 'center', justifyContent: 'center',
                    fontSize: 32,
                  }}>
                    {!product.image_url && '🍽️'}
                  </div>
                  <h4 style={{ color: '#e2e8f0', fontSize: 14, marginBottom: 4 }}>{product.name}</h4>
                  <p style={{ color: '#fbbf24', fontWeight: 700, fontSize: 16 }}>${product.price?.toFixed(2)}</p>
                </div>
              ))}
            </div>
          </div>

          {/* Panel derecho: Carrito */}
          <div className="card" style={{ position: 'sticky', top: 24, height: 'fit-content' }}>
            <h3 style={{ color: '#e2e8f0', marginBottom: 16, fontSize: 18 }}>🛒 Pedido Actual</h3>

            {cart.length === 0 ? (
              <p style={{ color: '#64748b', textAlign: 'center', padding: 30 }}>Selecciona productos del menú</p>
            ) : (
              <>
                <div style={{ display: 'flex', flexDirection: 'column', gap: 12, marginBottom: 16, maxHeight: 400, overflowY: 'auto' }}>
                  {cart.map(item => (
                    <div key={item.product_id} style={{
                      background: '#0f172a', borderRadius: 10, padding: 12,
                    }}>
                      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 8 }}>
                        <span style={{ color: '#e2e8f0', fontWeight: 600, fontSize: 14 }}>{item.name}</span>
                        <button
                          onClick={() => removeFromCart(item.product_id)}
                          style={{ background: 'none', border: 'none', color: '#ef4444', cursor: 'pointer', fontSize: 16 }}
                        >✕</button>
                      </div>
                      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 8 }}>
                        <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                          <button onClick={() => updateQuantity(item.product_id, -1)} style={{
                            width: 28, height: 28, borderRadius: 6, border: 'none',
                            background: '#334155', color: '#e2e8f0', cursor: 'pointer', fontWeight: 'bold',
                          }}>−</button>
                          <span style={{ color: '#e2e8f0', fontWeight: 600, minWidth: 20, textAlign: 'center' }}>{item.quantity}</span>
                          <button onClick={() => updateQuantity(item.product_id, 1)} style={{
                            width: 28, height: 28, borderRadius: 6, border: 'none',
                            background: '#334155', color: '#e2e8f0', cursor: 'pointer', fontWeight: 'bold',
                          }}>+</button>
                        </div>
                        <span style={{ color: '#fbbf24', fontWeight: 600 }}>${(item.price * item.quantity).toFixed(2)}</span>
                      </div>
                      <input
                        type="text"
                        placeholder="Notas: sin cebolla, etc."
                        className="input"
                        style={{ fontSize: 12, padding: '8px 10px' }}
                        value={item.notes}
                        onChange={(e) => updateItemNotes(item.product_id, e.target.value)}
                      />
                    </div>
                  ))}
                </div>

                <div style={{ borderTop: '1px solid #334155', paddingTop: 16, marginBottom: 16 }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 8 }}>
                    <span style={{ color: '#94a3b8' }}>Subtotal</span>
                    <span style={{ color: '#e2e8f0', fontWeight: 600 }}>${cartTotal.toFixed(2)}</span>
                  </div>
                  <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                    <span style={{ color: '#e2e8f0', fontWeight: 700, fontSize: 16 }}>Total</span>
                    <span style={{ color: '#fbbf24', fontWeight: 700, fontSize: 18 }}>${cartTotal.toFixed(2)}</span>
                  </div>
                </div>

                <textarea
                  placeholder="Notas generales del pedido..."
                  className="input"
                  style={{ marginBottom: 12, minHeight: 60, resize: 'vertical' }}
                  value={notes}
                  onChange={(e) => setNotes(e.target.value)}
                />

                <button
                  onClick={submitOrder}
                  className="btn btn-success"
                  style={{ width: '100%', padding: 14, fontSize: 16 }}
                  disabled={loading}
                >
                  {loading ? 'Enviando...' : '🚀 Enviar Pedido'}
                </button>
              </>
            )}
          </div>
        </div>
      ) : (
        /* Historial de pedidos */
        <div>
          <h2 style={{ color: '#e2e8f0', marginBottom: 20 }}>📋 Mis Pedidos</h2>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
            {myOrders.map(order => (
              <div key={order.id} className="card animate-fade-in">
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 12 }}>
                  <div>
                    <span style={{ color: '#38bdf8', fontWeight: 700, fontSize: 16 }}>{order.order_number}</span>
                    <span style={{ color: '#64748b', marginLeft: 12, fontSize: 13 }}>{formatDate(order.created_at)}</span>
                  </div>
                  <span style={{
                    padding: '4px 12px', borderRadius: 20, fontSize: 12, fontWeight: 600,
                    background: ORDER_STATUS_COLORS[order.status] + '20',
                    color: ORDER_STATUS_COLORS[order.status],
                  }}>
                    {ORDER_STATUS_LABELS[order.status]}
                  </span>
                </div>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <span style={{ color: '#94a3b8', fontSize: 14 }}>
                    {order.items?.length || 0} items · {order.order_type === 'dine_in' ? '🪑 Mesa' : '📦 ' + order.order_type}
                  </span>
                  <span style={{ color: '#fbbf24', fontWeight: 700, fontSize: 16 }}>
                    {formatCurrency(order.total)}
                  </span>
                </div>
              </div>
            ))}
            {myOrders.length === 0 && (
              <p style={{ color: '#64748b', textAlign: 'center', padding: 40 }}>No tienes pedidos registrados</p>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

export default WaiterPage;
